      "poi_id": "p103",
      "kind": "activity",
      "must_do_id": "m1",
      "note": "Kiến trúc kỳ quái như bước vào giấc mơ, cứ thong thả mà leo trèo ngó nghiêng."
    },
    {
      "poi_id": "p31",
      "kind": "meal",
      "must_do_id": null,
      "note": "Nồi lẩu bò sôi sùng sục, rau tươi nhúng ngập, ngồi xuống là ấm cả người."
    },
    {
      "poi_id": "p20",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chợ đêm lên đèn, đồ ăn vặt thơm lừng, cứ thả bộ mà ngắm người ta bán mua."
    }
  ]
}
