      "must_do_id": "m2",
      "note": "Bánh căn nóng giòn, nước chấm thơm lừng, ngồi xổm ăn mới đúng điệu."
    },
    {
      "poi_id": "p90",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thác đổ trắng xóa giữa rừng thông, đi bộ xuống là mát hết người."
    },
    {
      "poi_id": "p41",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bánh ướt mỏng tang, lòng gà dai giòn, chan nước mắm ngọt là hết sảy."
    },
    {
      "poi_id": "p355",
      "kind": "activity",
      "must_do_id": null,
      "note": "Leo lên đỉnh Langbiang, gió lộng, nhìn xuống thành phố như tấm thảm xanh."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Góc nhỏ ấm cúng, đồ ăn bày đẹp như tranh, ngồi nhâm nhi tới khuya cũng được."
    },
    {
      "poi_id": "p52",
      "kind": "activity",
      "must_do_id": null,
      "note": "Cà phê đêm ở Lululola, ánh đèn vàng, ngồi một góc nghe nhạc là đúng chất Đà Lạt."
    }
  ]
}
```

